const productTypeNames={en:['SNEAKERS','SLIDES','T-SHIRTS','JACKETS','HOODIES','HATS','SETS','WATCHES','EYEWEAR','HEADPHONES','SOCKS'],de:['SNEAKER','SANDALEN','T-SHIRTS','JACKEN','HOODIES','MÜTZEN','SETS','UHREN','BRILLEN','KOPFHÖRER','SOCKEN'],fr:['BASKETS','SANDALES','T-SHIRTS','VESTES','SWEATS','CASQUETTES','ENSEMBLES','MONTRES','LUNETTES','CASQUES','CHAUSSETTES'],es:['ZAPATILLAS','SANDALIAS','CAMISETAS','CHAQUETAS','SUDADERAS','GORRAS','CONJUNTOS','RELOJES','GAFAS','AURICULARES','CALCETINES'],it:['SNEAKER','SANDALI','T-SHIRT','GIACCHE','FELPE','CAPPELLI','COMPLETI','OROLOGI','OCCHIALI','CUFFIE','CALZINI'],pt:['TÉNIS','SANDÁLIAS','T-SHIRTS','CASACOS','HOODIES','BONÉS','CONJUNTOS','RELÓGIOS','ÓCULOS','AUSCULTADORES','MEIAS'],nl:['SNEAKERS','SLIPPERS','T-SHIRTS','JASSEN','HOODIES','PETTEN','SETS','HORLOGES','BRILLEN','KOPTELEFOONS','SOKKEN'],pl:['SNEAKERSY','KLAPKI','T-SHIRTY','KURTKI','BLUZY','CZAPKI','ZESTAWY','ZEGARKI','OKULARY','SŁUCHAWKI','SKARPETKI']};
function cards(l,lang){const x=routeCopy[lang]||routeCopy.en,names=categoryNames[lang]||categories,paths=["shoes","hoodies-sweaters","t-shirts","jackets","pants-shorts","headwear","accessories","jersey","electronics","other-stuff"];return `<div class="grid categories">${names.map((c,i)=>`<a href="${base}/${paths[i]}/" class="card"><b>0${i+1}</b><h3>${esc(c)}</h3><p>${i%2?x.cardOpen:x.cardBrowse}</p><span>FindSpreadsheet</span></a>`).join("")}</div>`}
function home(l,lang){const names=categoryNames[lang]||categories;return `<style>${cssV5}</style><main class="home-v5"><section class="vault-v5"><div class="vault-top"><span>SHEET JOYAGOO</span><span>${l.kicker}</span><span>01 / 2026</span></div><div class="orbit-v5"><i class="ring ring-a"></i><i class="ring ring-b"></i><figure><img src="/assets/float-v4.png" alt="${l.products}"></figure><a class="orb o-one" href="/${lang}/spreadsheet"><b>01</b><span>${l.sheet}</span></a><a class="orb o-two" href="/${lang}/joyagoo-qc-shipping-guide"><b>02</b><span>QC</span></a><a class="orb o-three" href="/${lang}/how-to-buy"><b>03</b><span>${l.how}</span></a><a class="orb o-four" href="/${lang}/products"><b>04</b><span>${l.products}</span></a><div class="vault-copy"><p class="eyebrow">${l.kicker}</p><h1>${l.title}</h1><p>${l.lead}</p></div></div><form class="vault-search" action="${base}/search.html"><input name="keywords" placeholder="${l.search}" aria-label="${l.search}"><button>${l.button}</button></form></section><section class="scroll-v5"><p class="eyebrow">${l.section}</p><article><span>01</span><h2>${facts[lang][0]}</h2><a href="/${lang}/spreadsheet">${l.sheet}</a></article><article><span>02</span><h2>${facts[lang][1]}</h2><a href="/${lang}/joyagoo-qc-shipping-guide">${l.article}</a></article><article><span>03</span><h2>${facts[lang][2]}</h2><a href="/${lang}/how-to-buy">${l.how}</a></article><article><span>04</span><h2>${facts[lang][3]}</h2><a href="/${lang}/faq">${l.faq}</a></article></section><section class="constellation-v5"><p class="eyebrow">${l.cats.toUpperCase()}</p><h2>${l.browse}</h2><div>${names.map((c,i)=>`<a href="${target(categories[i])}"><small>${String(i+1).padStart(2,'0')}</small>${esc(c)}</a>`).join('')}</div><a class="database-v5" href="${base}">${l.db}</a></section><section class="end-v5"><p>${l.countryText}</p></section></main>`}
function categoryPage(l,lang){const x=routeCopy[lang]||routeCopy.en;return `<main class="inner"><p class="eyebrow">${l.kicker}</p><h1>${l.cats}</h1><p class="lead">${x.categoryLead}</p>${cards(l,lang)}<section class="next"><p>${l.next}</p><h2>${l.sheet} → ${l.cats} → FindSpreadsheet</h2><a class="primary" href="/${lang}/spreadsheet">${l.sheet}</a></section></main>`}
function productPage(l,lang){const items=[["High-Quality Headphones 003","/electronics/high-quality-headphones-003-7113.html","/uploads/allimg/20260924/1-2609241T635U3.png","17.63"],["Stone Island Style Zip-Up Set","/ShortSets/stone-island-style-25ss-zip-up-hoodie-and-pants-set-7112.html","/uploads/allimg/20260924/1-260924160620360.jpg","25.62"],["Fashion Knit Sweater","/hoodies-sweaters/fashion-knit-sweater-7111.html","/uploads/allimg/20260924/1-260924160601c9.jpg","80.99"],["SU Tracksuit Set","/ShortSets/su-tracksuit-set-7110.html","/uploads/allimg/20260924/1-260924160512M5.jpg","67.49"],["Black Graphic Hoodie","/hoodies-sweaters/black-mm10-graphic-pullover-hoodie-003-keb-7109.html","/uploads/allimg/20260924/1-260924160109601.jpg","45.18"],["Casual Crewneck Sweatshirt","/hoodies-sweaters/casual-crewneck-sweatshirt-008-7108.html","/uploads/allimg/20260924/1-260924160109601.jpg","31.40"],["Premium Knit Sweater","/hoodies-sweaters/premium-fashion-knit-sweater-7107.html","/uploads/allimg/20260924/1-26092413161b50.jpg","53.17"],["Ami Heart Knit Sweater","/hoodies-sweaters/ami-heart-crewneck-knit-sweater-2025-7106.html","/uploads/allimg/20260924/1-26092413160D00.jpg","31.13"],["CP Company T-Shirt","/t-shirts/cp-company-t-shirt-2993.html","/uploads/allimg/20260924/1-260924131555956.jpg","34.90"],["Supreme Wallet","/accessories/supreme-wallet-2995.html","/uploads/allimg/20260924/1-260924131546130.jpg","29.50"],["Beats Studio Buds","/electronics/beats-studio-buds-wireless-headset-20-styles-664.html","/uploads/allimg/20260924/1-260924131535196.jpg","41.20"],["Qatar Jersey","/jersey/qatar-short-sleeve-suits-2249.html","/uploads/allimg/20260924/1-260924131522608.jpg","22.80"],["Wireless Earbuds Collection","/electronics/high-quality-headphones-003-7113.html","/uploads/allimg/20260924/1-2609241T635S3.webp","19.30"],["Protective Phone Case","/electronics/high-quality-headphones-003-7113.html","/uploads/allimg/20260924/1-2609241T6363M.webp","14.60"],["AI Smart Glasses","/electronics/high-quality-headphones-003-7113.html","/uploads/allimg/20260924/1-2609241T63B42.webp","49.90"],["Portable Camera","/electronics/high-quality-headphones-003-7113.html","/uploads/allimg/20260924/1-2609241T636237.webp","37.50"]];return `<style>.product-grid-16{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:35px}.product-grid-16 a{position:relative;background:#fff;padding-bottom:15px;overflow:hidden}.product-grid-16 img{display:block;width:100%;aspect-ratio:1/1;object-fit:cover}.product-grid-16 span{position:absolute;top:10px;left:10px;background:#111;color:#fff;padding:5px;font:700 .65rem Arial}.product-grid-16 h3{font-size:.9rem;margin:13px 13px 4px}.product-grid-16 p{font-size:.72rem;margin:0 13px;color:#59605f}@media(max-width:780px){.product-grid-16{grid-template-columns:repeat(2,1fr);gap:8px}.product-grid-16 h3{font-size:.78rem}}</style><main class="inner"><p class="eyebrow">PRODUCT DETAIL / 16 FINDS</p><h1>${l.products}</h1><p class="lead">Sixteen different FindSpreadsheet product details, with the current source images and USD references.</p><div class="product-grid-16">${items.map((x,i)=>`<a href="${base}${x[1]}"><img src="${base}${x[2]}" alt="${esc(x[0])}" loading="lazy"><span>${String(i+1).padStart(2,"0")}</span><h3>${x[0]}</h3><p>${x[3]} USD · View details</p></a>`).join("")}</div></main>`}
function sheetPage(l,lang){const x=routeCopy[lang]||routeCopy.en;return `<main class="inner guide"><p class="eyebrow">${l.sheet.toUpperCase()}</p><h1>${l.title}</h1><p class="lead">${x.sheetLead}</p><h2>${x.sheetHeads[0]}</h2><p>${facts[lang][0]} ${x.sheetTail}</p><h2>${x.sheetHeads[1]}</h2><p>${x.sheetMiddle}</p><h2>${x.sheetHeads[2]}</h2><p>${facts[lang][1]} ${x.sheetEnd}</p><a class="primary" href="${base}">${l.cta}</a></main>`}
function howPage(l,lang){const x=routeCopy[lang]||routeCopy.en;return `<main class="inner guide"><p class="eyebrow">${l.how.toUpperCase()}</p><h1>${l.how}: ${x.howTitle}</h1><p class="lead">${x.howLead}</p>${facts[lang].map((fact,i)=>`<article class="step"><b>0${i+1}</b><div><h2>${x.howHeads[i]}</h2><p>${fact}</p></div></article>`).join('')}<section class="notice"><strong>${x.country}</strong><p>${x.countryText}</p></section></main>`}
function articlePage(l,lang){const paras=[facts[lang][0],facts[lang][1],facts[lang][2],facts[lang][3]];return `<main class="article"><p class="eyebrow">${l.updated} · BUYING GUIDE</p><h1>Joyagoo QC, warehouse storage and shipping: a practical checklist</h1><p class="deck">A useful spreadsheet guide should reduce uncertainty before, during and after a product reaches a warehouse. This article focuses on what shoppers can verify and what remains outside anyone’s control.</p><h2>Start with a research question, not a promise</h2><p>${paras[0]} A focused category path helps visitors avoid endless scrolling and gives them a stable way to compare options. The point is not to label a product “safe” or “best”; it is to preserve the details that matter when you later inspect the actual item.</p><h2>QC is the decision point, not a decorative gallery</h2><p>${paras[1]} Treat the warehouse images as a time-sensitive review task. Check the selected variation, obvious shape and colour differences, measurements where available, hardware, stitching and visible condition. Ask for clarification through the official service when needed, and make the decision based on the specific order rather than an older image.</p><h2>Storage gives flexibility, not an excuse to forget the parcel</h2><p>${paras[2]} That matters when you want to group different purchases, but it also creates a practical checklist: track the storage date, decide what will travel together, and consider whether one parcel contains excessive weight or too many identical items. Customs and shipping rules vary by country, so a small personal shipment in one destination is not a universal rule.</p><h2>Estimated shipping and final shipping are different numbers</h2><p>${paras[3]} Plan a budget buffer rather than treating the first figure as final. Packaging, volumetric size, selected route, destination and optional parcel services can change the result. Review the route choices shown for your real destination and product mix, because restrictions can exclude some lines.</p><h2>For US and European shoppers, localisation needs substance</h2><p>${l.countryText} A localisation strategy is not merely a translated navigation bar. Each language version should explain the same core flow with the same level of detail, use a stable URL, link to its related category and guide pages, and keep a clear canonical relationship. That makes it easier for visitors to find the page that matches their language and for search engines to understand that the pages are intended variants rather than accidental duplicates.</p><h2>Use an independent site for discovery only</h2><p>This site is designed to help visitors search, compare and arrive at the right FindSpreadsheet page. It does not handle accounts, payments, warehouse operations, shipping or customer support. Keeping that boundary explicit improves clarity: the reader knows what the guide can answer and where the transaction must continue.</p><section class="next"><p>${l.next}</p><h2>Search a product direction on FindSpreadsheet.</h2><a class="primary" href="${base}">${l.cta}</a></section></main>`}
function faqPage(l,lang){const q=[['What is this site for?','It is an independent discovery guide for product research, category paths and practical buying checks.'],['Where do I continue to search?','Use the FindSpreadsheet button or a category card to open the corresponding search path.'],['Does this site take payment?','No. It does not provide checkout, wallets, warehouse work or shipping services.'],['What should I check after QC?','Review the item-specific photos promptly and make the decision from the actual warehouse record.'],['How long can items stay in storage?','The official guidance describes 90 days of free warehouse storage; verify current terms in your order flow.'],['Why can shipping change after submission?','The final amount can depend on the packed parcel’s actual size and weight, destination and available route.'],['Can any guide promise customs clearance?','No. Rules, inspections, taxes and restrictions depend on the destination and parcel.'],['Do language pages contain the same guide depth?','Yes. The site keeps a dedicated version for each supported language and the same core page structure.']];return `<main class="inner"><p class="eyebrow">${l.faq.toUpperCase()}</p><h1>${l.faq}</h1><p class="lead">Clear answers before you continue to a product search.</p><div class="faq">${q.map(([a,b],i)=>`<details ${i===0?'open':''}><summary>${a}</summary><p>${b}</p></details>`).join('')}</div></main>`}
function html(lang,route){currentRoute=route;currentLocalePath=routeNames[route];const l=locales[lang];const page={home:home,categories:categoryPage,products:productPage,article:articlePage,faq:faqPage,sheet:sheetPage,how:howPage}[route](l,lang);const routeSlug=routeNames[route];const canonical=`https://sheet-joyagoo.com/${lang}/${routeSlug}`.replace(/\/$/,'/');return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(l.title)} | Sheet Joyagoo</title><meta name="description" content="${esc(l.lead)}"><link rel="canonical" href="${canonical}">${Object.keys(locales).map(x=>`<link rel="alternate" hreflang="${x}" href="https://sheet-joyagoo.com/${x}/${routeSlug}">`).join('')}<link rel="alternate" hreflang="x-default" href="https://sheet-joyagoo.com/en/${routeSlug}"><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='12' fill='%23101316'/%3E%3Cpath d='M15 18h34v7H22v7h21v7H22v7h27v7H15z' fill='%23c6ff3c'/%3E%3C/svg%3E"><style>${css}${cssV2}${cssV3}${loloPalette}</style></head><body>${nav(l,lang)}${page}${footer(l,lang)}</body></html>`}
function profileHtml(lang,p,index){currentRoute='products';const l=locales[lang];const slug=`products/${p[0]}`;currentLocalePath=slug;const canonical=`https://sheet-joyagoo.com/${lang}/${slug}`;return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p[2])} | ${esc(l.products)} | Sheet Joyagoo</title><meta name="description" content="Product research profile for ${esc(p[2])}."><link rel="canonical" href="${canonical}">${Object.keys(locales).map(x=>`<link rel="alternate" hreflang="${x}" href="https://sheet-joyagoo.com/${x}/${slug}">`).join('')}<link rel="alternate" hreflang="x-default" href="https://sheet-joyagoo.com/en/${slug}"><style>${css}${cssV2}${cssV3}${loloPalette}</style></head><body>${nav(l,lang)}${productDossierPage(l,lang,p,index)}${footer(l,lang)}</body></html>`}
