productCataloguePage=(l,lang)=>{const x=routeCopy[lang]||routeCopy.en,types=productTypeNames[lang]||productTypeNames.en;let out=originalProductCataloguePage(l,lang).split('PRODUCT DETAIL PROFILES · 11 TYPES').join(x.productKicker).split('Choose a product profile for the full detail-page format, then use its live product button to continue directly on FindSpreadsheet.').join(x.productLead).split('OPEN DETAIL FORMAT').join(x.openDetail).split('LIVE PRODUCT').join(x.liveProduct);productProfiles.forEach((p,i)=>{out=out.split(p[1]).join(types[i])});return out};
